import sys
import math

def solve():
    s = sys.stdin.read().strip()
    if not s:
        return
    target_len = len(s)
    target_val = int(s)

    low = 1
    high = 10**6 + 100
    ans = 1

    while low <= high:
        mid = (low + high) // 2
        if mid == 1:
            digits = 1
        else:
            digits = sum(math.log10(i) for i in range(2, mid + 1)) + 1
        if digits == target_len:
            # Check exact value to distinguish between same length factorials
            if mid == 1:
                if target_val == 1:
                    ans = mid
                    break
                else:
                    low = mid + 1
                    continue
            # Compute factorial of mid using Python's arbitrary precision integers
            fact = 1
            for i in range(2, mid + 1):
                fact *= i
            if fact == target_val:
                ans = mid
                break
            elif fact < target_val:
                low = mid + 1
            else:
                high = mid - 1
        elif digits < target_len:
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

if __name__ == "__main__":
    solve()

import sys
import math

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        target = int(line)
    except ValueError:
        return

    if target == 1:
        print(1)
        return

    target_log = math.log10(target)
    current_log = 0.0
    n = 1

    while True:
        current_log += math.log10(n + 1)
        n += 1
        if current_log >= target_log:
            print(n)
            break

if __name__ == "__main__":
    solve()
